import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";
import "jsr:@supabase/functions-js/edge-runtime.d.ts";

Deno.serve(async (req: Request) => {
  // CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
      }
    });
  }

  try {
    const { documento_id, nivel_govbr = 'Prata' } = await req.json();
    if (!documento_id) throw new Error("ID do documento ├® obrigat├│rio");

    const clientIp = req.headers.get('x-real-ip') || req.headers.get('x-forwarded-for')?.split(',')[0].trim() || 'IP n├úo detectado';

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    // Identificar o usu├írio que est├í chamando a fun├º├úo (o assinante) de forma segura
    const authHeader = req.headers.get('Authorization');
    let signerUserId: string | undefined;

    if (authHeader) {
      const token = authHeader.replace('Bearer ', '');
      const { data: { user } } = await supabase.auth.getUser(token);
      signerUserId = user?.id;
    }

    // 1. Buscar metadados do documento
    const { data: doc, error: docError } = await supabase
      .from('documentos')
      .select('*')
      .eq('id', documento_id)
      .single();

    if (docError || !doc) throw new Error(`Documento n├úo encontrado: ${docError?.message || 'Sem dados'}`);

    // 2. Buscar o nome e CPF do assinante no perfil
    let assinanteNome = 'Usu├írio Identificado';
    let assinanteCpf = 'N├úo informado';

    // Usamos o ID do usu├írio autenticado se dispon├¡vel, caso contr├írio fallback para enviado_por
    const targetUserId = signerUserId || doc.enviado_por;

    if (targetUserId) {
      const { data: profile } = await supabase
        .from('profiles')
        .select('nome, cpf')
        .eq('user_id', targetUserId)
        .maybeSingle();

      if (profile?.nome) {
        assinanteNome = profile.nome;
      }
      if (profile?.cpf) {
        assinanteCpf = profile.cpf;
      }
    }

    // 3. Baixar o arquivo do Storage para processar o Hash REAL
    const { data: fileData, error: storageError } = await supabase.storage
      .from('documentos')
      .download(doc.arquivo_path);

    if (storageError || !fileData) throw new Error(`Falha ao baixar arquivo: ${storageError?.message || 'Arquivo n├úo encontrado no storage'}`);

    // 4. Calcular Hash SHA-256 do arquivo REAL
    const arrayBuffer = await fileData.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', arrayBuffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');

    // Determinar classifica├º├úo legal conforme Lei 14.063/2020
    const eQualificada = nivel_govbr === 'Ouro';
    const tipoLegal = eQualificada
      ? 'Assinatura Eletr├┤nica Qualificada (ICP-Brasil)'
      : 'Assinatura Eletr├┤nica Avan├ºada';

    // 5. Metadados de assinatura conforme Lei 14.063/2020
    const signatureMetadata = {
      provedor: 'Gov.br',
      algoritmo: 'SHA-256',
      tipo: tipoLegal,
      lei_referencia: 'Lei n┬║ 14.063/2020',
      assinante_nome: assinanteNome,
      assinante_cpf: assinanteCpf,
      assinante_id: targetUserId,
      conexao_ip: clientIp,
      data_assinatura: new Date().toISOString(),
      hash_original: hashHex,
      nivel_certificado: eQualificada ? 'Certificado Digital ICP-Brasil' : 'N├¡vel Prata/Ouro (Gov.br)',
      autenticidade_url: `${req.headers.get('origin') || 'https://camara.digital'}/verificar/${hashHex}`
    };

    // 6. Atualizar o documento com o HASH REAL e metadados
    const { error: updateError } = await supabase
      .from('documentos')
      .update({
        arquivo_hash: hashHex,
        assinado: true,
        assinatura_metadata: signatureMetadata
      })
      .eq('id', documento_id);

    if (updateError) throw new Error(`Erro ao atualizar documento: ${updateError.message}`);

    // 7. Registrar na tabela de assinaturas
    await supabase.from('assinaturas').insert({
      tenant_id: doc.tenant_id,
      documento_id: doc.id,
      user_id: targetUserId,
      status: 'assinado',
      token: `govbr_hash_${hashHex.substring(0, 16)}`,
      signed_at: new Date().toISOString()
    });

    return new Response(JSON.stringify({
      success: true,
      hash: hashHex,
      message: `Documento assinado como ${tipoLegal} com sucesso.`
    }), {
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST' }
    });

  } catch (err: any) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    console.error('ERROR SIGN-DOCUMENT:', errorMessage);
    return new Response(JSON.stringify({ error: errorMessage }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST' }
    });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";
import { PDFDocument, rgb } from "https://esm.sh/pdf-lib@1.17.1";
import "jsr:@supabase/functions-js/edge-runtime.d.ts";

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
      }
    });
  }

  try {
    const { documento_id } = await req.json();
    if (!documento_id) throw new Error("ID do documento ├® obrigat├│rio");

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const { data: doc, error: docError } = await supabase
      .from('documentos')
      .select('*')
      .eq('id', documento_id)
      .single();

    if (docError || !doc) throw new Error("Documento n├úo encontrado");
    if (!doc.assinado) throw new Error("O documento ainda n├úo possui uma assinatura digital");

    const { data: fileData, error: storageError } = await supabase.storage
      .from('documentos')
      .download(doc.arquivo_path);

    if (storageError || !fileData) throw new Error("Falha ao recuperar o arquivo original");

    const pdfDoc = await PDFDocument.load(await fileData.arrayBuffer());
    const pages = pdfDoc.getPages();
    const fontBold = await pdfDoc.embedStandardFont('Helvetica-Bold');
    const fontRegular = await pdfDoc.embedStandardFont('Helvetica');

    const meta = doc.assinatura_metadata;
    const rawCpf = meta?.assinante_cpf?.replace(/\D/g, '') || '';
    const maskedCpf = rawCpf.length >= 11
      ? `${rawCpf.substring(0, 3)}.***.***-${rawCpf.substring(rawCpf.length - 2)}`
      : '###.***.***-##';

    const assinanteInfo = `${meta?.assinante_nome || 'Usu├írio Identificado'} (CPF: ${maskedCpf})`;
    const tipoAssinatura = meta?.tipo || 'Assinatura Eletr├┤nica';
    const verifyUrl = `${req.headers.get('origin') || 'https://camara.digital'}/verificar/${doc.arquivo_hash}`;

    // Aplicar selo em todas as p├íginas
    for (const page of pages) {
      const { width } = page.getSize();

      // Selo de Autenticidade no Rodap├®
      page.drawRectangle({
        x: 0,
        y: 0,
        width: width,
        height: 65,
        color: rgb(0.95, 0.97, 1.0), // Azul bem claro
      });

      page.drawText(`AUTENTICIDADE GARANTIDA - LEI N┬║ 14.063/2020`, {
        x: 20,
        y: 48,
        size: 10,
        font: fontBold,
        color: rgb(0, 0.2, 0.5),
      });

      page.drawText(`${tipoAssinatura}`, {
        x: 20,
        y: 36,
        size: 8,
        font: fontBold,
        color: rgb(0.1, 0.1, 0.1),
      });

      page.drawText(`Assinado por: ${assinanteInfo}`, {
        x: 20,
        y: 24,
        size: 8,
        font: fontRegular,
        color: rgb(0.2, 0.2, 0.2),
      });

      page.drawText(`Valide em: ${verifyUrl}`, {
        x: 20,
        y: 10,
        size: 7,
        font: fontRegular,
        color: rgb(0.3, 0.3, 0.3),
      });
    }

    const pdfBytes = await pdfDoc.save();

    return new Response(pdfBytes, {
      headers: {
        'Content-Type': 'application/pdf',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST'
      }
    });

  } catch (err: any) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    console.error('ERROR STAMP-PDF:', errorMessage);
    return new Response(JSON.stringify({ error: errorMessage }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST' }
    });
  }
});
